// Przygotowanie logu oraz payloadu Notion - brak wysylki sieciowej bez zgody
const run = $input.item.json;
const metrics = run.metrics || {};

const notionPayload = {
  parent: { database_id: $env.NOTION_DAAS_DB_ID || 'NOTION_DB_ID_PLACEHOLDER' },
  properties: {
    'Projekt': { title: [{ text: { content: 'DaaS Engine' } }] },
    'Status': { select: { name: 'Pilot Active' } },
    'Run ID': { rich_text: [{ text: { content: run.run_id || '' } }] },
    'Data Status': { select: { name: run.data_status || 'UNKNOWN' } },
    'Przychód': { number: metrics.revenue_total || 0 },
    'Marża %': { number: metrics.margin_pct || 0 },
    'Wykonano': { date: { start: run.finished_at || new Date().toISOString() } },
    'Wlasciciel': { people: [] },
    'Next Action': { rich_text: [{ text: { content: 'Przeglad raportu tygodniowego przez Michala' } }] }
  }
};

return {
  status: 'SUCCESS',
  run_id: run.run_id,
  records_processed: run.records_processed,
  execution_time_sec: run.execution_time_sec,
  report_html_path: run.report_html_path,
  notion_payload: notionPayload
};

// Obsluga awarii - formatowanie alertu Slack (bez bezposredniej wysylki bez credentials)
const run = $input.item.json;
const slackAlertPayload = {
  channel: $env.SLACK_ALERT_CHANNEL || '#edge-os',
  text: `⚠️ [DaaS Alert] Awaria runu pipeline: ${run.pipeline || 'unknown'}`,
  blocks: [
    {
      type: 'header',
      text: { type: 'plain_text', text: 'DaaS Engine Alert — Awaria Runu' }
    },
    {
      type: 'section',
      text: {
        type: 'mrkdwn',
        text: `*Status:* ${run.run_status || 'FAILED'}\n*Blad:* ${run.error || 'Nieznany blad wykonania'}\n*Run ID:* \`${run.run_id || 'n/a'}\`\n*Czas:* ${new Date().toISOString()}`
      }
    },
    {
      type: 'context',
      elements: [
        { type: 'mrkdwn', text: 'Wymagana interwencja operatora (Michal). Brak danych klienta w alercie.' }
      ]
    }
  ]
};

return {
  status: 'FAILED',
  error: run.error || 'Pipeline run failed',
  slack_payload: slackAlertPayload
};
